      "## Preise",
      "Die Tageskarte kostet für Erwachsene <strong>10,50 €</strong> unter der Woche und <strong>11,50 €</strong> an Samstagen, Sonn- und Feiertagen, für Kinder und Jugendliche von 6 bis 17 <strong>8 €</strong> bzw. <strong>8,50 €</strong> und für Kleinkinder von 3 bis 5 <strong>4 €</strong> bzw. <strong>4,50 €</strong>. Pensionist:innen zahlen unter der Woche 8 €, Studierende, Menschen mit Behinderung und Präsenzdiener 8 € bzw. 9 €. Die Garderobe kostet 1 € pro Person, ein Paar Straßenschuhe nimmt sie umsonst.",
      "Die <strong>Abendkarte</strong> gilt montags ab 15:30 Uhr, dienstags und donnerstags ab 18:30 Uhr, mittwochs, samstags, an Sonn- und Feiertagen ab 16:30 Uhr. Sie kostet für Erwachsene <strong>7,50 €</strong> bzw. <strong>8,50 €</strong>, für Kinder und Jugendliche 6 € bzw. 6,50 €, für Kleinkinder 3 € bzw. 3,50 €.",
      "Am Wochenende und an Feiertagen gibt es <strong>Familienkarten</strong>: ein Erwachsener mit einem Kind von 6 bis 17 um 17,50 €, zwei Erwachsene mit einem Kind um 28 €, jedes weitere Kind 7 €; mit einem Kleinkind von 3 bis 5 sind es 13,50 € bzw. 24 €, jedes weitere Kleinkind 3,50 €. Die <strong>Vorverkaufskarte</strong> kostet 35 € und ist 40 € wert. Die Saisonkarte kostet für Erwachsene 260 € und für Jugendliche 210 €, die Halbsaisonkarte ab 1. Jänner 130 € bzw. 105 €. Öffentliche Wiener Schulen haben freien Eintritt.",
      "## Verleih und Schleifen",
