      "## Seit 1909",
      "Die Kunsteisbahn wurde am <strong>10. November 1909</strong> eröffnet, nach Angaben des Betreibers als erste Freiluft-Kunsteisbahn der Welt. Aufs Dach kam die Eisfläche 1974.",
