      "Im Festsaal spielen Orchester und Bigband der <strong>Wiener Klangvereinigung</strong>, im Zeremoniensaal <strong>Mama's Soul Club</strong>; im Wintergarten, im Orchestergang und im Rittersaal sind unter anderem Classic Sound Vienna, die Slörfcäts und die Jazzophoniker angekündigt. Im Gartensaal öffnet ab <strong>20 Uhr</strong> das Café Mozart, in der Gardehalle I ab <strong>22 Uhr</strong> eine Karaoke-Bar, im Forum legt ab <strong>23 Uhr</strong> die Radio Wien Ball-Disco auf. Der Veranstalter behält sich Änderungen vor; zu welchen Uhrzeiten die einzelnen Bands spielen, steht noch nicht im Programm.",
