      "Getanzt wird in vielen Räumen zugleich: im Festsaal, Zeremoniensaal, Metternichsaal und Rittersaal, in den Radetzky- und den Maria-Theresien-Appartements, im Gartensaal, im Forum, im Schatzkammersaal und in der Spanischen Hofreitschule samt Foyer.",
