      "Am <strong>Donnerstag, 4. Februar 2027</strong>, wird die Wiener Staatsoper am Opernring 2 zum Ballsaal: Dann ist der <strong>69. Wiener Opernball</strong>. Einlass ist um <strong>20:15 Uhr</strong>, die Eröffnung beginnt um <strong>22 Uhr</strong>, und offiziell endet der Ball um <strong>5 Uhr</strong> früh.",
