      "Der Juristenball 2027 findet am Faschingsamstag, <strong>Samstag, 6. Februar 2027</strong>, in der <strong>Hofburg Vienna</strong> am Heldenplatz statt. <strong>Einlass ist um 20 Uhr</strong>, der Ball beginnt um <strong>21:30 Uhr</strong> und endet um <strong>5 Uhr</strong> früh. Getanzt wird im Festsaal, im Zeremoniensaal, im Metternichsaal, im Rittersaal und in der Geheimen Ratstube; im Forum im Parterre läuft das Justiz-Clubbing. Das Motto lautet „Dancing Queen – Die Tanzende Muse“, nach 50 Jahren ABBA-Album und dem 200. Geburtstag von Josef Strauss.",
      "## Programm",
      "Ab 20 Uhr empfangen Walzermädchen die Gäste im Foyer. Um <strong>21:30 Uhr</strong> eröffnen Debütantinnen und Debütanten unter der Leitung von Prof. Thomas Schäfer-Elmayer den Ball. Verena Tranker und Michael C. Havlicek singen „Tanzen möcht’ ich“ aus Emmerich Kálmáns „Csárdásfürstin“, es tanzt die Walzerformation der Tanzschule Elmayer, dann heißt es „Alles Walzer“. Das Eröffnungskomitee tanzt neben Polonaise und Walzern als Neueinstudierung die Polka Mazurka „Die tanzende Muse“ op. 266 von Josef Strauss.",
