      "Um <strong>Mitternacht</strong> spielt die Show ABBA 99. Die <strong>Publikumsquadrille</strong> im Festsaal gibt es zweimal, um <strong>0:30 Uhr</strong> und um <strong>2 Uhr</strong>, ebenfalls geleitet von Schäfer-Elmayer. Von 23 bis 2 Uhr stehen im Festsaal Taxitänzer bereit. Im Forum legen die DJs Waldi & Wolf von 21:30 bis 5 Uhr auf. Lose des Charity-Gewinnspiels für „Wider die Gewalt“ kosten <strong>10 Euro</strong>, gezogen wird um 1:30 Uhr im Zeremoniensaal.",
      "## Dresscode",
