      "Erhältlich sind noch die <strong>ermäßigte Eintrittskarte um 180 Euro</strong>, die es nur zusammen mit einer Sitzplatzbuchung gibt, die <strong>Berufsanwärterkarte um 160 Euro</strong> (mit Legitimation, ohne Sitzplatz) und das <strong>Justiz-Clubbing-DeLuxe-Ticket um 90 Euro</strong>: Es gilt ab 21:30 Uhr im Forum und von 1 bis 5 Uhr für den ganzen Ball, ohne Sitzplatz. Die Preise der Sitzplätze stehen nur im Saalplan des Shops. Vor dem Ball gibt es ab 18:30 Uhr ein <strong>Pre Ball Gala Dinner</strong> mit Weinbegleitung um <strong>195 Euro</strong> (nur zusammen mit einer Eintrittskarte), mit Sitzplatz für die ganze Ballnacht in der Trabantenstube um <strong>220 Euro</strong>. Die Garderobe ist im Eintritt enthalten (höchstens drei Stück); gekaufte Karten nimmt der Veranstalter nicht zurück.",
      "## Anreise",
      "Die Hofburg Vienna liegt am <strong>Heldenplatz, 1010 Wien</strong>; das Forum mit dem Justiz-Clubbing hat den Eingang Heldenplatz. Der Veranstalter nennt als Anreise die U3-Stationen Herrengasse und Volkstheater sowie die Straßenbahnlinien 1, 2, 71 und D am Ring. In der Hofburg tanzt eine Woche zuvor, am 30. Jänner, der <a href=\"/veranstaltungen/wiener-aerzteball-2027/\" title=\"75. Wiener Ärzteball 2027\">Wiener Ärzteball</a>, zwei Tage danach, am 8. Februar, die <a href=\"/veranstaltungen/rudolfina-redoute-2027/\" title=\"Rudolfina-Redoute 2027\">Rudolfina-Redoute</a>.",
