      "Herren kommen in <strong>Frack, Smoking oder Uniform</strong> im klassischen Stil, schwarz und mit schwarzen Schuhen; die Uniform als „großer Gesellschaftsanzug“ mit Dekoration. Krawatten, Trachtenbänder sowie gestreifte oder bunte Smokingjacken sind ausgeschlossen, ebenso Anzüge, Trachtenanzüge, Kilt und Kostüme. Herren tragen keine Maske, und Verkleidungen aller Art sind trotz des Namens Redoute nicht erlaubt. Bei unpassender Kleidung kann das Ballkomitee den Eintritt verwehren; Masken und Fliegen hält die Abendkassa, solange der Vorrat reicht, zum Kauf bereit.",
